// Characterization tests: pin current client-visible behavior, quirks included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 0.5, BIG: 150 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST',
  headers: { 'content-type': 'application/json' },
  body: raw ?? JSON.stringify(body),
})

test('POST /orders creates order: 201, string id, echoed items, total', async () => {
  const items = [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /^application\/json/)
  const order = await res.json()
  assert.equal(typeof order.id, 'string')
  assert.deepEqual(order.items, items)
  assert.equal(order.total, 45)
  assert.deepEqual(Object.keys(order).sort(), ['id', 'items', 'total'])
})

test('ids are sequential strings', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total is floored to whole euros', async () => {
  const order = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  assert.equal(order.total, 25) // 25.5
})

test('10% discount only when total is strictly over 100', async () => {
  const at100 = await (await post({ items: [{ sku: 'A', qty: 10 }] })).json()
  assert.equal(at100.total, 100)
  const over = await (await post({ items: [{ sku: 'A', qty: 11 }] })).json()
  assert.equal(over.total, 99) // 110 - 11
  const big = await (await post({ items: [{ sku: 'BIG', qty: 1 }] })).json()
  assert.equal(big.total, 135)
  const frac = await (await post({ items: [{ sku: 'C', qty: 203 }] })).json()
  assert.equal(frac.total, 91) // 101.5 * 0.9 = 91.35 -> 91
})

test('GET /orders/:id returns the created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET unknown order returns 200 with error body (not 404)', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('POST /orders validation returns 400 { error: "items required" }', async () => {
  const cases = [
    [{}], [{ items: [] }], [{ items: 'x' }], [{ items: {} }], [undefined, '{not json'],
  ]
  for (const [body, raw] of cases) {
    const res = await post(body, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('empty body is treated as {} and rejected with 400', async () => {
  const res = await post(undefined, '')
  assert.equal(res.status, 400)
})

test('failed validation does not consume an id', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  await post({ items: [] })
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('unknown routes and methods return 404 { error: "no route" }', async () => {
  for (const [method, path] of [
    ['GET', '/'], ['GET', '/orders'], ['PUT', '/orders'], ['DELETE', '/orders/1'],
    ['POST', '/orders/1'], ['GET', '/orders/1/items'],
  ]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})

test('query string is ignored for routing', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}?x=1`)
  assert.deepEqual(await res.json(), created)
})

test('unknown SKU (no price) yields total null in JSON, still 201', async () => {
  const res = await post({ items: [{ sku: 'NOPE', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})
